function decide(cacheControl, hasETag) {
  const cc = String(cacheControl || '').toLowerCase();
  const has = (t) => cc.split(',').map((s) => s.trim()).includes(t);

  if (has('no-store')) return ['no-store', '完全不存储，每次重新请求'];
  if (has('no-cache')) return ['revalidate', '可缓存，但每次使用前必须校验（可能得到 304）'];

  const m = cc.match(/max-age=(\d+)/);
  if (m && Number(m[1]) > 0) {
    return hasETag
      ? ['fresh+revalidate', '强缓存 ' + m[1] + ' 秒；过期后可用 ETag 协商']
      : ['fresh', '强缓存 ' + m[1] + ' 秒；过期后需完整重新获取'];
  }
  return ['revalidate', '无新鲜度信息，必须校验'];
}

const CASES = [
  ['public, max-age=31536000, immutable', true],
  ['no-cache', true],
  ['no-store', false],
  ['max-age=0', true],
  ['private, max-age=60', false],
];

for (const [cc, etag] of CASES) {
  const [mode, note] = decide(cc, etag);
  console.log('Cache-Control: ' + cc + (etag ? '   [有 ETag]' : '   [无 ETag]'));
  console.log('  判定: ' + mode + ' —— ' + note);
  console.log('');
}
console.log('关键区分：no-cache 不是「不缓存」（它仍会缓存，只是每次必须校验）；no-store 才是真的不存储。');
